// pxl-tool/spec/cmd.rs

//! The core's machine and its protocols, the UI's and the text
//! device's, generated by xpute's generator where each one's `gen` says.

use xpute_gen::spec::cmd::protocol_outputs;
use xpute_gen::spec::machine;

use super::Output;
use crate::root;

pub fn outputs() -> Result<Vec<Output>, String> {
    let mut out = machine::outputs(&root(), "spec/client/core/sys/machine.json")?;
    out.extend(protocol_outputs(
        &root(),
        &[
            "spec/client/core/door/ui.json",
            "spec/client/core/sys/io/text.json",
        ],
    )?);
    Ok(out
        .into_iter()
        .map(|o| Output::new(&o.path, o.text))
        .collect())
}
